export const totalPlanned = 50;

export const lockedCount = pros.filter((p) => p.status === 'locked').length;
export const draftedCount = pros.filter((p) => p.status !== 'candidate').length;
export const illustratedCount = pros.filter((p) => Boolean(p.front)).length;

export const featuredPros = pros.filter((p) => p.status === 'locked').slice(0, 6);

export function getPro(slug: string) {
  return pros.find((p) => p.slug === slug);
}
